#!/usr/bin/env python3
# SPDX-License-Identifier: CC0-1.0
"""Generate the inputs of the engine-specific MathML corpus (`testdata/vectors/mathml/`).

Three files, all kind `mathml` (input `{tex, display}`, expected `html` and `math_errors`):

- `math-core-0.9.json`: hand-picked snapshots of the filter and the style normaliser
  (docs/spec/lfm-1.md sec. 7.3);
- `s10-corpus.json`: the 63 representative snippets of spike S10 (ADR 0002, appendix), in the
  order and with the names of the appendix table;
- `s10-probes.json`: single-command probes (symbols and operator names, one- and two-argument
  commands, environments, miscellaneous constructs), regenerated for M4 along the lines of the
  S10 method (ADR 0002 "Math coverage").

Expected values are filled by the runner's bless mode
(`LESSDUGIN_BLESS=1 LESSDUGIN_VECTORS=mathml/ cargo test -p lessdugin-markdown --test vectors`)
and reviewed: they record which commands math-core 0.9.0 renders (`math_errors` 0) and which are
math errors (1), so a math-core bump that changes coverage or markup shows up in review.
Existing expected values are kept when a vector's input did not change.
"""
import json, os, sys

ROOT = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")

DESC = ("input: {tex, display}; expected: html (the document HTML of $tex$, or $$tex$$ when display "
        "is true) and math_errors. Inputs generated by mathml/gen_mathml.py; expected values blessed "
        "with LESSDUGIN_BLESS=1 and reviewed. Every html is also checked by the allowlist checker, "
        "for sanitiser equality and for unknown math-core style declarations.")


def MM(name, tex, display=False):
    return {"name": name, "input": {"tex": tex, "display": display}, "expected": {"html": None, "math_errors": None}}


FILES = {}


def F(path, desc, vectors):
    names = [v["name"] for v in vectors]
    assert len(names) == len(set(names)), f"duplicate names in {path}"
    FILES[path] = {"behaviour": "lfm/1", "kind": "mathml", "description": desc + " " + DESC, "vectors": vectors}


# ------------------------------------------------------------------ snapshots
